// n8n Code node: "Forecast stock-outs" (Run once for all items)
const products = $('Read products').all().map(i => i.json);
const lines = $('Read order lines').all().map(i => i.json);
const suppliers = $('Read suppliers').all().map(i => i.json);
const incoming = $('Read incoming').all().map(i => i.json)
  .filter(r => r.sku && ['in_transit', 'in_production', 'ordered'].includes(String(r.status).trim()));

const WINDOW = 28;          // days of sales history for velocity
const SAFETY = 7;           // safety buffer, days
const HORIZON = 90;         // forecast horizon, days
const COVER = 30;           // new order should cover this many days after arrival
const today = $now.startOf('day');
const parseDate = v => { const s = String(v ?? '').trim(); let m;
  if ((m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/))) return DateTime.fromObject({ year: +m[1], month: +m[2], day: +m[3] });
  if ((m = s.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})/))) return DateTime.fromObject({ year: +m[3], month: +m[2], day: +m[1] });
  if ((m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/))) return DateTime.fromObject({ year: +m[3], month: +m[1], day: +m[2] });
  if (/^\d{5}(\.\d+)?$/.test(s)) return DateTime.fromISO('1899-12-30').plus({ days: Math.floor(+s) });
  return DateTime.fromISO(s); };
// works with ISO, dd.mm.yyyy, mm/dd/yyyy and Sheets serial dates (any spreadsheet locale)
const dayIdx = s => Math.round(parseDate(s).startOf('day').diff(today, 'days').days);
const fmt = n => today.plus({ days: n }).toFormat('LLL d');

const sold = {};
for (const l of lines) {
  const d = dayIdx(l.created_at);
  if (d <= 0 && d > -WINDOW) sold[l.sku] = (sold[l.sku] || 0) + Number(l.qty || 0);
}

const critical = [], orderNow = [], covered = [];
for (const p of products) {
  const sku = p.sku, stock = Number(p.stock) || 0, price = Number(p.price) || 0;
  const vel = (sold[sku] || 0) / WINDOW;
  if (vel <= 0) continue;
  const sup = suppliers.find(s => s.sku === sku) || {};
  const lead = Number(sup.lead_time_days) || 21;
  const moq = Number(sup.min_order_qty) || 1;
  const pos = incoming.filter(r => r.sku === sku)
    .map(r => ({ po: r.po_number, qty: Number(r.qty) || 0, status: r.status, day: Math.max(0, dayIdx(r.eta)) }))
    .sort((a, b) => a.day - b.day);

  // day-by-day simulation: with and without incoming supply
  let s1 = stock, s0 = stock, outWith = null, outWithout = null, stockAtLead = null;
  for (let d = 1; d <= HORIZON; d++) {
    for (const po of pos) if (po.day === d) s1 += po.qty;
    s1 -= vel; s0 -= vel;
    if (outWith === null && s1 <= 0) outWith = d;
    if (outWithout === null && s0 <= 0) outWithout = d;
    if (d === lead) stockAtLead = Math.max(0, s1);
  }
  const incomingQty = pos.reduce((s, x) => s + x.qty, 0);
  const need = Math.ceil(vel * (lead + COVER) - (stockAtLead ?? 0) - pos.filter(x => x.day > lead).reduce((s, x) => s + x.qty, 0));
  const orderQty = need > 0 ? Math.max(moq, Math.ceil(need / moq) * moq) : 0;
  const base = { sku, name: p.name, stock, vel: Math.round(vel * 10) / 10, lead, supplier: sup.supplier || '—', pos, orderQty, price };

  if (outWith !== null && outWith <= lead) {
    // runs out before any new order could arrive
    const nextPo = pos.find(x => x.day > outWith);
    const backDay = nextPo ? Math.min(nextPo.day, lead) : lead;
    const gap = Math.max(1, backDay - outWith);
    critical.push({ ...base, outDay: outWith, outDate: fmt(outWith), nextPo, gap, backDate: fmt(backDay),
      lost: Math.round(gap * vel * price) });
  } else if (outWith !== null && outWith <= lead + SAFETY) {
    orderNow.push({ ...base, outDay: outWith, outDate: fmt(outWith), orderBy: fmt(Math.max(0, outWith - lead)) });
  } else if (outWithout !== null && outWithout <= lead + SAFETY && incomingQty > 0) {
    covered.push({ ...base, outDayWithout: outWithout, outDate: fmt(outWithout) });
  }
}
critical.sort((a, b) => a.outDay - b.outDay);
orderNow.sort((a, b) => a.outDay - b.outDay);
return [{ json: { date: today.toFormat('yyyy-MM-dd'), critical, orderNow, covered,
  total: critical.length + orderNow.length + covered.length,
  lost_total: critical.reduce((s, c) => s + c.lost, 0) } }];

// n8n Code node: "Format alert"
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const f = $('Forecast stock-outs').first().json;
const st = { in_transit: 'in transit', in_production: 'in production', ordered: 'ordered' };
const L = [];
L.push(`📦 <b>GearUp · stock-out forecast</b> (${f.date})`);
L.push(`<i>Based on current stock, last 28 days of sales and supplier deliveries</i>`);
if (f.critical.length) {
  L.push('', `🔴 <b>Will run out before supply arrives (${f.critical.length})</b>`);
  for (const c of f.critical) {
    const po = c.nextPo ? `${esc(c.nextPo.po)} (${c.nextPo.qty} pcs, ${st[c.nextPo.status] || c.nextPo.status}) arrives ${c.backDate}` : `no incoming supply, earliest new delivery ${c.backDate} (${c.lead}d lead time)`;
    L.push(`• <b>${esc(c.name)}</b>: ${c.stock} left, sells ${c.vel}/day → out <b>${c.outDate}</b>. ${po} → <b>${c.gap} days</b> without stock, ~$${c.lost.toLocaleString('en-US')} lost sales.${c.orderQty ? ` Order ${c.orderQty} pcs from ${esc(c.supplier)}.` : ''}`);
  }
}
if (f.orderNow.length) {
  L.push('', `🟠 <b>Order now (${f.orderNow.length})</b>`);
  for (const c of f.orderNow)
    L.push(`• <b>${esc(c.name)}</b>: out ${c.outDate}, lead time ${c.lead}d → order <b>${c.orderQty} pcs</b> from ${esc(c.supplier)} by <b>${c.orderBy}</b>.`);
}
if (f.covered.length) {
  L.push('', `🟢 <b>Covered by incoming supply (${f.covered.length})</b>`);
  for (const c of f.covered)
    L.push(`• ${esc(c.name)}: would run out ${c.outDate}, but ${c.pos.map(p => `${esc(p.po)} (${p.qty} pcs, ${st[p.status] || p.status})`).join(', ')} covers it.`);
}
const ai = String($json.text || '').replace(/\*\*/g, '').replace(/^#+\s*/gm, '').trim();
if (ai) L.push('', `🧠 <i>${esc(ai)}</i>`);
return [{ json: { text: L.join('\n').slice(0, 4000) } }];
